/* ============================================================================
 * ADEPTIO Pulse — Flow Inspection : Mobile Payment Module · RCA METADATA REGISTRY (incident pop-up)
 * nodes[<id>]      → editable-default description, customer-facing page + journey
 *                    step, sibling systems to open next, owning team (owners MOCK).
 * indicators["<nodeId>.<objective label>"] → first checks + questions to ask.
 * Keys mirror data/manifest.js exactly. All checks are READ-ONLY: we detect,
 * trace, score and ticket; your team owns the fix. Bands are ILLUSTRATIVE.
 * ==========================================================================*/
window.ADEPTIO_RCA = {
 nodes: {
  "client": { desc: "The customer handset and mobile banking app - the only hop in the journey the bank does not run. It opens Pay Bill at S01 with local validation and a feature-flag fetch, and renders the receipt at S12. With no SDK in the app there is no client-side latency telemetry: coverage comes from the synthetic journey S02-S12 plus store release health.", page: "Pay Bill entry, biller picker and receipt screens · steps S01, S12", systems: ["telco","edge","gw"],
   owner: { team: "Digital Channels", name: "U Kyaw Zin Htun", channel: "#dc-mobile-app · ext. 411 (mock)", escalate: "No owner response in 15 min: page the Digital Channels duty lead. A staged-rollout halt or store rollback needs Head of Channels sign-off." } },
  "telco": { desc: "The customer data path: handset radio, carrier APN and core, internet transit, then DNS resolution and the TLS session to the bank host at S02. If this hop fails nothing above it is reachable, and the bank owns none of it. Depends on carrier radio and transit, public resolvers and the certificate chain served at the edge.", page: "Every screen that calls the API; reads to the customer as a spinner or no-connection · step S02", systems: ["edge","client","gw"],
   owner: { team: "Network Ops - Carrier Liaison", name: "Daw Thiri Aung", channel: "#noc-carrier · ext. 421 (mock)", escalate: "Vendor path: raise with the carrier NOC under the data-transit SLA; no acknowledgement in 15 min, escalate via Vendor Mgmt to the carrier account manager. Confirm 2-of-3 vantages first - never page on one." } },
  "edge": { desc: "The bank perimeter at S03: firewall, WAF and load-balancer pair in front of the public VIP. It terminates TLS, filters requests and picks a healthy gateway node, so a pool or ruleset fault here removes capacity for every screen at once. Depends on the appliance pair, the LB pool health-check definition and the certificate inventory.", page: "All app screens behind the public VIP · step S03", systems: ["gw","telco","auth"],
   owner: { team: "Network Ops", name: "U Myo Min Latt", channel: "#noc-edge · ext. 422 (mock)", escalate: "No response in 15 min: page the Network Ops duty engineer, then the platform on-call manager. Suspected hardware raises an appliance-vendor TAC case in parallel." } },
  "gw": { desc: "The API gateway fronting POST /v1/bills/pay at S04: auth plugin, rate limits, route table and per-route access logging. Every Pay Bill request crosses it, so route latency and 5xx here are felt immediately by the customer. Depends on the ingress node pool, the auth service and the downstream orchestrator.", page: "Bill-pay submit and every authenticated screen · step S04", systems: ["edge","auth","pay"],
   owner: { team: "Platform Engineering", name: "Daw Ei Ei Khaing", channel: "#plat-gateway · ext. 431 (mock)", escalate: "No response in 15 min: page the Platform on-call. Deploy rollback for a route regression is the release manager's call, with Payments informed." } },
  "auth": { desc: "Auth and session services at S05: token validation, session load from cache and the policy that lets the payment proceed. It is on the critical path for login and for every authenticated Pay Bill call. Depends on the token store cache, the signing key set and clocks that agree.", page: "Login, re-authentication and session-expiry prompts · step S05", systems: ["gw","otp","pay"],
   owner: { team: "Identity & Access", name: "U Zaw Lin Naing", channel: "#iam-auth · ext. 441 (mock)", escalate: "No response in 15 min: page the Identity on-call. A suspected key rotation or session-policy change escalates jointly to Security Engineering." } },
  "otp": { desc: "The OTP and notification service that generates, sends and verifies the payment challenge at S06 and issues receipts at S12. Pay Bill cannot complete without it, so a stalled challenge reads to the customer as a broken payment. Depends on the SMS gateway route, the challenge store and the message templates.", page: "OTP entry screen and push/SMS receipt · steps S06, S12", systems: ["smsgw","auth","mq"],
   owner: { team: "Identity & Access - Notify", name: "Daw Nwe Nwe Win", channel: "#iam-otp · ext. 442 (mock)", escalate: "No response in 15 min: page the Identity on-call and open the aggregator case in parallel - the OTP service and the SMS route fail identically from the customer seat." } },
  "smsgw": { desc: "The partner SMS gateway and telco SMSC path that actually delivers OTPs and SMS receipts at S06 and S12: SMPP binds, submissions and DLR receipts. It is vendor-operated - the bank measures it but cannot change it. Depends on the aggregator binds, each carrier SMSC and the registered sender ID.", page: "OTP entry screen - the customer waits for a code that never arrives · step S06", systems: ["otp","auth","client"],
   owner: { team: "Vendor Mgmt - SMS Aggregator Liaison", name: "U Aung Ko Ko", channel: "#vendor-sms · ext. 471 (mock)", escalate: "Vendor path: P1 to the aggregator NOC quoting per-carrier DLR and affected-customer count; 15-min acknowledgement, then the account manager and a request for an alternate route." } },
  "pay": { desc: "The payment orchestrator running the Pay Bill saga across S07-S11: bill inquiry, fraud and limit checks, balance read, core posting and the biller credit leg, with retries and idempotency keys. It is where a technical fault becomes a customer-visible decline. Depends on the accounts service, core banking, the biller hub and its own saga store.", page: "Bill details, confirm and processing screens · steps S07-S11", systems: ["core","acct","bhub"],
   owner: { team: "Payments Squad", name: "Daw Su Myat Noe", channel: "#pay-squad · ext. 451 (mock)", escalate: "No response in 15 min: page the Payments on-call. Anything with money debited and not credited goes straight to the Head of Payments, evidence bundle attached." } },
  "acct": { desc: "The accounts and balance service that reads available balance for the payment decision at S09 and serves statement reads. It sits between the orchestrator and the read replica, so its answer decides whether a funded customer is declined. Depends on the DB replica, its connection pool and the core read adapter.", page: "Available balance on the confirm screen; balance and statement views · step S09", systems: ["dbr","pay","core"],
   owner: { team: "Core Ops - Account Services", name: "U Thant Zin Oo", channel: "#core-accounts · ext. 452 (mock)", escalate: "No response in 15 min: page the Core Ops on-call. A suspected stale-read decline is escalated jointly with Data Platform and treated as P1." } },
  "dbr": { desc: "The read replica behind balance reads, with its SAN storage, serving S09. It carries the balance the payment decision is made on, which makes replication lag here a money problem rather than a reporting one. Depends on primary write throughput, the replication apply path and storage latency.", page: "Available balance before confirm; the insufficient-funds message · step S09", systems: ["acct","core","pay"],
   owner: { team: "Data Platform - DBA", name: "Daw Hnin Wai Phyo", channel: "#data-dba · ext. 461 (mock)", escalate: "No response in 15 min: page the DBA on-call. Storage-array faults raise a vendor TAC case alongside, since IOPS and latency are array-side only." } },
  "core": { desc: "Core banking at S10 and S14: posting the debit, writing journal and GL entries, and running the EOD batch. Nothing in the payment is real until the core posts it, so a stall here creates pending items and orphaned debits downstream. Depends on the core DB and its SAN, the interface adapter and the batch scheduler.", page: "Processing screen after confirm; balance and statement afterwards · steps S10, S14", systems: ["pay","dbr","mq"],
   owner: { team: "Core Ops", name: "U Soe Naing Win", channel: "#core-ops · ext. 462 (mock)", escalate: "No response in 15 min: page the Core Ops on-call and notify the Head of Operations. Posting or failover faults open a core-vendor support case at the same time." } },
  "bhub": { desc: "The biller hub and aggregator that routes to each biller through per-biller adapters, for both the bill inquiry at S07 and the credit leg at S11. One bad adapter fails one biller; a hub-wide fault fails all of them. Depends on partner links (IPsec or leased), per-adapter credentials and each biller platform.", page: "Biller list, bill details and payment result · steps S07, S11", systems: ["biller","pay","bbatch"],
   owner: { team: "Payments Squad - Biller Integrations", name: "Daw Yamin Htay", channel: "#pay-billers · ext. 453 (mock)", escalate: "No response in 15 min: page the Payments on-call. Aggregator-side faults raise a P1 with the aggregator NOC through Vendor Mgmt, with per-adapter evidence." } },
  "biller": { desc: "The billers themselves - utilities and telco top-up providers - which confirm the amount due at S07 and credit the customer account at S11. They sit outside the bank: their downtime is the customer's failed payment. Depends on the partner link, the hub adapter mapping, and each biller platform and cut-off.", page: "Bill amount shown, payment result and top-up delivery · steps S07, S11", systems: ["bhub","bbatch","recon"],
   owner: { team: "Vendor Mgmt - Biller Partnerships", name: "U Htet Aung Kyaw", channel: "#vendor-billers · ext. 472 (mock)", escalate: "Vendor path: P1 to the biller operations desk quoting affected-transaction count and value; 15-min acknowledgement, then the relationship owner via Vendor Mgmt." } },
  "bbatch": { desc: "The batch side of the biller relationship: the advice file we send, the biller confirmation cycle and the retry queue for legs that did not confirm online, spanning S11 into S14. It is where an online timeout is either resolved or turned into a settlement exception. Depends on the SFTP path, the cut-off schedule and the biller batch window.", page: "No live screen - surfaces later as a missing payment in history or a reversal · steps S11, S14", systems: ["biller","bhub","recon"],
   owner: { team: "Payments Ops - Settlement Files", name: "Daw Khin Mar Cho", channel: "#pay-settlement · ext. 473 (mock)", escalate: "No response in 15 min: page Payments Ops. A missed cut-off escalates the same day to the Head of Payments and the biller relationship owner." } },
  "mq": { desc: "The broker and history consumer that write the payment into statement and transaction history asynchronously at S13, and carry notification events for S12. The money can be entirely correct while this lags - the customer just cannot see it. Depends on the broker cluster, the consumer group and the history store write path.", page: "Transaction history and statement tab, plus the push receipt · steps S12, S13", systems: ["core","otp","recon"],
   owner: { team: "Platform Engineering - Messaging", name: "U Pyae Phyo Han", channel: "#plat-messaging · ext. 432 (mock)", escalate: "No response in 15 min: page the Platform on-call. If payments are correct and only history lags, hold at P2 and brief the contact centre with expected catch-up time." } },
  "recon": { desc: "T+1 reconciliation and settlement at S14: the three-way match of gateway, core and biller records on once, amount, order and window. It is the last check that the money story is consistent, and where every earlier silent failure eventually surfaces. Depends on settlement file arrival, the match rule set and clocks that agree across contributing systems.", page: "No customer screen - drives disputes, reversals and statement corrections · step S14", systems: ["core","bhub","biller"],
   owner: { team: "Recon & Settlement Ops", name: "Daw Moe Moe Aye", channel: "#recon-ops · ext. 481 (mock)", escalate: "No response in 15 min: page the Recon duty officer. Unmatched value above the standing threshold escalates to Finance and the Head of Payments the same morning." } }
 },
 indicators: {
  /* --- P-A front-end & access (S01-S04) --- */
  "client.Journey success": {
   checks: ["Read the synthetic journey log for the FIRST failing step (S02-S12) - the first red step names the layer, the last one only names the symptom.", "Split journey success by app version and by carrier: a single-version or single-carrier dip is a release or ingress problem, not a platform one.", "Check gw.5xx rate and pay.Decline anomaly for the same minutes - all green here with the journey red is the silent business-failure signature.", "Confirm NTP offset on the probe hosts (chronyc tracking, band <100 ms) before trusting the step timeline; skew invents phantom ordering."],
   questions: ["Which step failed first, and what were the asserted versus observed values on that step?", "Was a mobile release, feature flag, gateway route or rule version pushed inside the failure window?"] },
  "client.Crash-free sessions": {
   checks: ["Pull crash-free sessions as 100 minus crashRate from the Play Developer Reporting crashRateMetricSet; read vitals.anrrate separately - ANR is its own resource.", "Dimension distinctUsers by version: a dip concentrated in the newest build is a release regression, not an outage.", "Treat this as release health only - store telemetry is aggregated and lags hours to about a day, so do not page on it.", "Confirm client.Journey success and gw.5xx rate stayed flat; a client-only dip does not implicate the backend."],
   questions: ["Which build introduced the regression, and what adoption share does it already hold?", "Is a staged-rollout halt or rollback already in flight on the store console?"] },
  "client.Review error signal": {
   checks: ["Read the App Store Connect customerReviews feed and the Play review stream for the last 48 h, tagged by version.", "Apply the standing rule: minus 0.3 stars in 48 h, or a 3x volume spike against the rolling 7-day mean.", "Bucket the complaints by journey wording - login, OTP, payment, history - the wording usually names the failing step.", "Line the spike up against the incident timeline, allowing for the lag; reviews trail the event by hours."],
   questions: ["Do the complaints cluster on one version, one carrier or one biller?", "Does contact-centre volume corroborate the spike, or is this review-channel noise only?"] },
  "telco.DNS resolve": {
   checks: ["Run dig +short <api host> @<resolver> A from two in-country resolvers and one regional vantage; compare the answer set against the expected VIP list.", "Apply 2-of-3 agreement before declaring an outage - a single failing vantage is not an incident.", "Read the split: only in-country failing points at the local ISP resolver or GSLB steering; all vantages failing points at the zone or origin.", "Spot-check integrity with dig +dnssec +cd and confirm the zone serial and TTLs are what we published."],
   questions: ["Did the carrier change resolvers or push a filtering or DNS64 policy in this window?", "Which resolver IPs return the bad or empty answer, and how much TTL is left on the cached record?"] },
  "telco.TCP connect p95": {
   checks: ["Split the hops with curl -w: time_namelookup, time_connect, time_appconnect, time_starttransfer, time_total; TCP RTT = connect minus namelookup.", "Compare in-country (typical <30 ms) against regional (typical <120 ms) vantages to separate last mile from transit.", "Take the verdict from the TCP-connect probe, not ICMP - firewalls deprioritise ping; keep ICMP for loss and RTT quality only.", "Read edge interface counters (delta ifInErrors 1.3.6.1.2.1.2.2.1.14, ifInDiscards, ifHCInOctets) to clear the bank side of the path."],
   questions: ["Which carrier and APN are the affected sessions on, and is one peering path common to all of them?", "Has the carrier published a transit or maintenance notice covering this window?"] },
  "telco.TLS handshake p95": {
   checks: ["Isolate TLS cost as time_appconnect minus time_connect from the same curl -w run: normal TCP with high TLS points at the handshake, not the path.", "Confirm the chain and negotiated cipher are unchanged with openssl s_client -connect <host>:443 -servername <host>.", "Read edge.TLS termination p95 for the same window - a flat edge means the cost was added on the carrier or client side.", "Compare the handset and OS mix of affected sessions; a client stack change moves handshake cost too."],
   questions: ["Was the cipher list, OCSP stapling or certificate chain changed at the edge recently?", "Do offshore vantages see the same handshake cost, or is this in-country only?"] },
  "telco.Packet loss": {
   checks: ["Measure ICMP loss alongside the TCP-connect probe per vantage; alert on >1% sustained, never on a single sample.", "Read jitter with the loss (typical <20 ms) - loss with jitter suggests congestion, clean loss suggests a policer or shaper.", "Pair ifOperStatus (1.3.6.1.2.1.2.2.1.8) with ifAdminStatus (1.3.6.1.2.1.2.2.1.7) on the border interfaces to separate a failed link from a planned-down one.", "Check whether the loss curve tracks time-of-day peaks - a repeatable peak-hour shape is capacity, not fault."],
   questions: ["Which segment does the carrier's own probe place the loss on - radio, APN or transit?", "Is there an open maintenance or capacity ticket on this route?"] },
  "edge.Availability": {
   checks: ["GET the public VIP over HTTPS with the Host header pinned and assert status AND a body token - status alone is not proof.", "Read LB pool member state (F5 ltmPoolMbrStatusAvailState 1.3.6.1.4.1.3375.2.2.5.6.2.1.5; ltmPoolMemberAvailabilityState is deprecated).", "Pair ifOperStatus with ifAdminStatus on the member links to tell a failure from a planned-down interface.", "Read sysUpTime (1.3.6.1.2.1.1.3.0) on both appliances - a decrease between polls means a restart happened."],
   questions: ["Is the VIP failing on one appliance of the pair or both, and did a failover run?", "Which change ticket covers this window - WAF ruleset, pool config or firmware?"] },
  "edge.TLS termination p95": {
   checks: ["Compare edge TLS termination p95 against telco.TLS handshake p95 minute for minute; a gap that exists only at the edge is local.", "Read appliance CPU via the vendor MIB (resolve per device - there is no universal CPU OID) and session or conntrack usage against max (band <70%).", "Check edge.Pool members up: handshake cost climbs when survivors absorb the whole VIP load.", "Read the WAF block rate against the trailing 7-day baseline - inspection cost rises with rule volume."],
   questions: ["How many TLS sessions per second is each surviving member carrying versus its rated capacity?", "Was hardware offload, the cipher list or the WAF ruleset version changed recently?"] },
  "edge.Cert days-to-expiry": {
   checks: ["Read live expiry: echo | openssl s_client -connect <host>:443 -servername <host> 2>/dev/null | openssl x509 -noout -enddate.", "Use the boolean gate for alerting: openssl x509 -checkend 2592000 (30 days).", "Walk every VIP, SNI and partner-facing listener, not just the primary host - fleet inventory is where these get missed.", "Confirm the served chain matches the intended issuer and that intermediates are present."],
   questions: ["Who holds the renewal task, and has the CSR been issued yet?", "Do any partner or client-pinned trust stores need the new certificate before cutover?"] },
  "edge.Pool members up": {
   checks: ["Read member state by SNMP (ltmPoolMbrStatusAvailState) or the LB API; the standing alert is 2-of-4 members.", "For each down member check whether the backing node fails /ready while still passing /health - that one should be drained, not restarted.", "Pair ifOperStatus with ifAdminStatus on the member links to confirm failed rather than administratively disabled.", "Watch gw.5xx rate and edge.TLS termination p95 in the same window - survivors carrying the load is the usual second symptom."],
   questions: ["Are the down members on one chassis, blade or hypervisor host?", "What does the pool health-check actually assert, and did it change with the last deploy?"] },
  "gw.Availability": {
   checks: ["Probe GET /gateway/health (liveness) and /ready (drain-aware) separately - they answer different questions and only /ready should drive the pool.", "Run the seeded synthetic POST /v1/bills/pay and assert a JSON field (status ACCEPTED plus a non-empty paymentId), never HTTP status alone.", "If nodes pass /health and fail /ready, read the dependency they report - the fault is downstream, not in the gateway.", "Check edge.Pool members up: the gateway can be healthy while the path to it is not."],
   questions: ["Which downstream dependency is /ready reporting unhealthy?", "Is this every ingress node or a subset, and what do the failing ones have in common?"] },
  "gw.Route p95": {
   checks: ["Roll up per-route p95 from the access-log stream at 1 min and confirm POST /v1/bills/pay is the affected route, not the gateway as a whole.", "Subtract downstream time: compare against pay.Orchestration p95 for the same window to locate where the latency was added.", "Read gw.Worker saturation and the 429 rate together - retry storms self-amplify and turn slow into failed.", "Overlay the deploy marker feed: a step change at a deploy boundary is a regression, not load."],
   questions: ["What changed in the last deploy to this route - timeout budget, plugin chain or connection pool?", "Is the added time inside the gateway, or is it waiting on the orchestrator?"] },
  "gw.5xx rate": {
   checks: ["Break the count down by status code, route and upstream: 502 and 504 point downstream, 500 points at the gateway itself.", "Run the contract-drift probe - fetch the OpenAPI doc, hash it, diff against the pinned baseline, then validate a live response against the pinned schema.", "Separate 429s from 5xx: rate-limit rejections have a different owner and a different remedy (band 429s <0.1% of requests).", "Check concentration - errors on one ingress node means a node, errors spread evenly means the route or an upstream."],
   questions: ["What is the exact upstream error body behind the 5xx, and which service emits it?", "Which build serves this route now, and does the deploy timestamp line up with the first bad minute?"] },
  "gw.Worker saturation": {
   checks: ["Read worker or thread-pool utilisation and queue depth per ingress node against configured max (band <80%).", "Decide whether saturation follows request rate (load) or upstream latency (blocked workers) - the second is the usual case in payments.", "Read host CPU (hrProcessorLoad 1.3.6.1.2.1.25.3.3.1.2, averaged per core) and memory (memAvailReal vs memTotalReal) on the gateway nodes.", "Look for a retry storm: 429 rate plus repeated identical idempotency keys inflate demand without new customers."],
   questions: ["How many workers are blocked on downstream calls right now, and against which upstream?", "Have pool size or upstream timeout budgets changed since the last known-good build?"] },
  /* --- P-B service orchestration (S05-S09) --- */
  "auth.Login synthetic": {
   checks: ["Read the seeded synthetic login result and the exact assertion that failed - this is the only check that proves the whole front door.", "Probe /auth/health and read the token store with a read-only cache PING plus hit-ratio read.", "Split the failure by phase: token issue, session load, or waiting on the OTP challenge at S06 - a stuck OTP loop reads as a login failure.", "Read auth.Auth p95 and auth.Token refresh fail in the same window to tell slow from broken."],
   questions: ["Did the synthetic fail on credentials, on session load, or waiting for the OTP to arrive?", "Was a session policy, token TTL or cache node changed in this window?"] },
  "auth.Availability": {
   checks: ["Probe /auth/health at 30 s and confirm more than one node is failing before calling it service-wide.", "Read the cache PING and hit ratio - a cold or evicting session cache presents as auth unavailability.", "Read sysUpTime (1.3.6.1.2.1.1.3.0) on the auth nodes for an unplanned restart between polls.", "Confirm the gateway auth plugin can reach the service at all; an edge or route fault looks identical from the customer seat."],
   questions: ["Are all auth nodes affected, or is one failing health while still in the LB pool?", "What state is the cache cluster in - node loss, eviction spike or memory ceiling?"] },
  "auth.Auth p95": {
   checks: ["Read auth p95 from the service log stream, split by operation: validate, refresh, session load.", "Read cache hit ratio - a hit-ratio drop moves the work to the backing store and surfaces as p95.", "Read host CPU and memory on the auth nodes (hrProcessorLoad; memAvailReal vs memTotalReal) before blaming the code path.", "Compare with gw.Route p95: a flat gateway means the time is being spent inside auth."],
   questions: ["Which operation carries the added latency, and against which dependency?", "Has token verification fallen back from cache to a remote lookup for any class of session?"] },
  "auth.Token refresh fail": {
   checks: ["Read the refresh failure rate from the service log split by reason: expired, revoked, bad signature, clock skew.", "Check NTP offset on issuing and validating nodes (chronyc tracking; band <100 ms, alert >1 s) - skew rejects tokens that are actually valid.", "Confirm the JWKS served matches what validators have cached, and note any rotation in the window.", "Check whether failures concentrate on one client version holding an unsupported refresh flow."],
   questions: ["Was a signing key rotated, and did every validator pick up the new key set?", "Do failures cluster by client version, by node, or by session age band?"] },
  "otp.Challenge→verify success": {
   checks: ["Run the end-to-end OTP loop on a test MSISDN per carrier - request, receive, verify - asserting the code actually arrives and validates.", "Split the funnel into issued, delivered (DLR), entered and verified: issued-vs-delivered is a carrier problem, delivered-vs-entered is a customer or UX problem.", "Read the expiry-before-entry rate - slow delivery turns into verify failures with no error logged anywhere.", "Read smsgw.DLR rate (worst carrier) and smsgw.Time-to-deliver p90 per carrier, never blended."],
   questions: ["Which carrier and sender ID are the failures concentrated on?", "Is the OTP validity window still longer than the current delivery p90 for that carrier?"] },
  "otp.Availability": {
   checks: ["Probe the OTP service health endpoint and confirm both the generate and the verify paths answer.", "Read the SMPP bind state and enquire_link keepalive (command_id 0x00000015, response 0x80000015); alert on two consecutive missed responses.", "Check the challenge store for eviction or capacity limits - a lost challenge verifies as a wrong code.", "Read auth.Login synthetic for the same window: OTP down surfaces to the customer as a login failure."],
   questions: ["Is the outage in the OTP service itself or in the SMS route it depends on?", "How many challenges are issued but now unverifiable, and what message are those customers seeing?"] },
  "otp.OTP issue p95": {
   checks: ["Read issue p95 from the service log split into generate time and submit-to-aggregator time.", "Measure the aggregator submit_sm (0x00000004) acknowledgement latency and the bind state per route.", "Compare with smsgw.Time-to-deliver p90: slow issue with normal delivery is bank-side, the reverse is carrier-side.", "Read challenge-store latency and notify-service queue depth for a local bottleneck."],
   questions: ["Is the aggregator acknowledging submissions slowly, or is our generate path the bottleneck?", "Are we being throttled on a route, and what submission rate is contracted?"] },
  "smsgw.Availability": {
   checks: ["Confirm the SMPP transceiver bind is established per aggregator route and that enquire_link (0x00000015) is answered by enquire_link_resp (0x80000015).", "Alert only after two consecutive missed keepalives - single misses are normal churn.", "Read the partner API echo as a second signal where a REST route runs alongside SMPP.", "Confirm deliver_sm (0x00000005) DLR PDUs are still arriving - that proves the return direction is alive."],
   questions: ["Which bind and which route is down, and is the aggregator failing over to an alternate SMSC?", "What is the aggregator incident reference, severity and stated ETA?"] },
  "smsgw.DLR rate (worst carrier)": {
   checks: ["Measure DELIVRD divided by submitted per carrier AND per sender ID - never blended; one failing carrier hides inside a healthy aggregate.", "Split UNDELIV from REJECTD: a rise in REJECTD is usually sender-ID or content filtering, not network.", "Corroborate with the test-MSISDN loop on the same carrier before escalating to the vendor.", "Count affected customers in the window (issued minus delivered) so the vendor ticket carries impact, not just a percentage."],
   questions: ["Does the aggregator see the same per-carrier split, and on which SMSC route?", "Was the sender ID, template or content changed, or newly filtered by that carrier?"] },
  "smsgw.Time-to-deliver p90": {
   checks: ["Measure submit-time to DLR-timestamp per carrier (typical p95 <30 s, p99 <60 s).", "Confirm our clock and the DLR clock agree (NTP offset <100 ms) before trusting the delta.", "Locate the queue: submit acks fast with DLR slow is the aggregator or carrier; submit acks slow is our submission path.", "Read otp.Challenge→verify success - delivery slower than the OTP validity window produces silent verify failures."],
   questions: ["Where is the queue sitting - our submission, the aggregator, or the carrier SMSC?", "Can the aggregator move this traffic class to an alternate binding for the duration?"] },
  "pay.Decline anomaly (10m sust.)": {
   checks: ["Split the decline mix by reason code over the last 10 minutes: insufficient funds, limit, fraud rule, biller reject, technical.", "If insufficient-funds declines dominate while every component reads green, go straight to dbr.Replication lag and the seeded balance assertion - that is the silent false-decline fingerprint.", "Corroborate lag with a heartbeat-table timestamp delta: Seconds_Behind_Source reports 0 when no event is being processed, so a stalled replica can read healthy.", "Read bhub.Adapter error and biller.Credit-leg success for a biller-side reject wave.", "Overlay fraud rule-version deploy markers - a block-rate spike right after a rule push is a misfire, not fraud."],
   questions: ["What is the reason-code split versus the same hour yesterday?", "Are the declines concentrated on one biller, one channel or one customer segment?", "Was a limit, rule version or replica topology change made inside this window?"] },
  "pay.Availability": {
   checks: ["Probe the orchestrator /health and /ready separately; passing /health while failing /ready means a downstream dependency, so drain rather than restart.", "Run the seeded synthetic Pay Bill and record which step it stops at - S07 inquiry, S09 balance, S10 posting or S11 credit leg.", "Read the saga store for in-flight transactions stuck in one state; the stuck state names the hop that stopped answering.", "Check core.Availability and bhub.Availability before routing the ticket to the orchestrator itself."],
   questions: ["How many sagas are in flight, and in which states right now?", "Which dependency timed out first in the trace of a failing transaction?"] },
  "pay.Orchestration p95": {
   checks: ["Break p95 into per-hop spans: inquiry S07, fraud S08, balance S09, posting S10, credit leg S11.", "Confirm each inner timeout budget is smaller than its caller's - otherwise retries stack and one slow hop stalls the whole saga.", "Compare with gw.Route p95 to see how much of the customer-visible wait this layer owns.", "Read retry counts per hop: retries multiply latency long before they change the outcome."],
   questions: ["Which hop owns the added time, and what is its contracted timeout?", "Is the retry policy amplifying a partner slowdown into a customer-visible timeout?"] },
  "pay.Technical decline": {
   checks: ["Split technical declines by originating hop and error class from the orchestrator log.", "Run the orphaned-debit sweep over the last 1-2 h: any decline with a matching posted debit is a business failure, not a technical one.", "Run the idempotency replay assertion against the seeded biller - same key twice must return the original result and post once.", "Compare with bhub.Biller timeout and core.Posting p95 for the upstream cause."],
   questions: ["Do any of these declines have a matching debit in the core journal?", "Which error class dominates - timeout, schema rejection, or a mapped biller error?"] },
  "acct.Read p95": {
   checks: ["Read balance-read p95 from the service log and compare with dbr.Query p95 to see how much of it is database time.", "Read connection-pool utilisation (active over max, band <80%) - pool exhaustion presents as app-tier latency.", "Run the deep canary query on a seeded row rather than SELECT 1; a bounded indexed read catches locks, bad plans and storage stalls.", "Confirm whether reads have moved to the primary or a second replica during this window."],
   questions: ["Is the added time in the query, in the pool wait, or in the adapter?", "Did a plan change, statistics refresh or index build land recently?"] },
  "acct.Stale-read assert fails": {
   checks: ["Read the failing assertion line itself: the seeded funded account must read its known balance - capture expected versus observed.", "Read dbr.Replication lag for the same minute and corroborate with the heartbeat-table timestamp delta; the lag metric can read 0 while stalled.", "Read pay.Decline anomaly for an insufficient-funds skew - that pair is scenario D, the silent false-decline fingerprint from the fault matrix.", "Confirm whether the payment path is pinned to the replica and whether any read-your-writes rule exists at all."],
   questions: ["How many customer declines in this window are attributable to a stale read, and what is their value?", "Can balance reads for the payment path be pinned to the primary while the replica catches up?"] },
  "acct.Availability": {
   checks: ["Probe the accounts service /health and /ready, and confirm the canary query still returns the seeded row.", "Read sysUpTime on the app nodes for an unplanned restart, and check whether all nodes or one are affected.", "Read connection-pool state - a fully exhausted pool presents as unavailability, not slowness.", "Confirm dbr.Availability and core.Availability before routing the ticket to the accounts service."],
   questions: ["Is the service down, or up and unable to obtain a database connection?", "Which replica is the service pointed at right now, and what state is it in?"] },
  "acct.Conn pool": {
   checks: ["Read active versus max connections per node (band <80%), not a cluster-wide average that hides one hot node.", "Pair saturation with acct.Read p95 - the two together confirm exhaustion rather than a slow query.", "Look for long-running or leaked sessions holding connections; read the oldest open session age.", "Check whether upstream retries (pay.Orchestration p95) are multiplying connection demand."],
   questions: ["Are connections held by long-running queries, or by callers that never release them?", "What is the configured max, and when was it last reviewed against traffic growth?"] },
  "dbr.Availability": {
   checks: ["Run the deep canary query on a seeded Pay Bill row - SELECT 1 proves the listener and nothing else.", "Confirm the replica accepts connections and is not paused, in recovery, or fenced.", "Read sysUpTime on the replica host and the SAN path state for an unplanned restart or storage event.", "Read acct.Availability and acct.Conn pool - the app tier fails first and loudest when the replica goes."],
   questions: ["Is the replica down, blocked, or simply unreachable from the app subnet?", "Is there a healthy alternate replica, and what would reads see if we pointed at it?"] },
  "dbr.Replication lag": {
   checks: ["Read the lag directly: MySQL Seconds_Behind_Source from SHOW REPLICA STATUS (the pre-8.0.22 Seconds_Behind_Master naming is deprecated - label it per the running version); Postgres write_lag, flush_lag, replay_lag from pg_stat_replication.", "Corroborate with a heartbeat-table timestamp delta - the value reports 0 when no event is being processed, so a stalled replica can read perfectly healthy.", "Read dbr.Disk IO latency and array write latency (storage-array API or vendor MIB; no standard MIB exists) - storage stalls are the usual cause.", "Convert lag into customer impact: run the seeded balance assertion and read acct.Stale-read assert fails (warn 5 s, crit 30 s on this row)."],
   questions: ["Is the replica applying, waiting on I/O, or blocked behind one long transaction on the primary?", "How far back does the stale read reach, and how many declines fall inside that window?"] },
  "dbr.Query p95": {
   checks: ["Read query p95 on the replica and compare the same statements on the primary to separate plan from platform.", "Check whether lag and query p95 rose together - apply-thread contention slows reads and lags at the same time.", "Read disk IO latency (write latency band <10 ms) and buffer-cache hit ratio on the replica.", "Confirm no reporting job or full-table sweep is running against this replica - continuous sweeps are the classic self-inflicted cause."],
   questions: ["What is the slowest statement in the window, and has its plan changed?", "Is any batch, export or analytics workload pointed at this replica right now?"] },
  "dbr.Disk IO latency": {
   checks: ["Read latency and IOPS from the storage-array API or the vendor MIB - there is no standard MIB for these, so resolve per array.", "Read capacity as hrStorageUsed (1.3.6.1.2.1.25.2.3.1.6) over hrStorageSize (1.3.6.1.2.1.25.2.3.1.5) times hrStorageAllocationUnits; band <80% used.", "Read this as a slope, not a spike - storage creep shows up as a trend across days before it shows as an incident.", "Check whether the array is running a rebuild, snapshot or replication job in this window."],
   questions: ["Which volumes and which controller show the latency, and is that load shared with another system?", "At the current growth rate, what date does this estate hit the capacity threshold?"] },
  /* --- P-C money movement (S10-S12) --- */
  "core.Availability": {
   checks: ["Read the core interface heartbeat - a read-only balance enquiry or echo on a seeded account through the real adapter, not just a socket check.", "TCP-connect to the core adapter port for the availability verdict; ICMP is deprioritised and can be misleading either way.", "Read core.Pending-age p95: a core that answers heartbeats while pending-age climbs is stuck, not down.", "Read sysUpTime on both core nodes and confirm whether a failover started and did not complete."],
   questions: ["Which core node is active, and did a failover begin and stall?", "What is the current unposted and in-flight item count, and is it growing?"] },
  "core.Posting p95": {
   checks: ["Read posting p95 and the posting error-code mix from the core interface log.", "Check the EOD and batch window marker feed first - the markers are what separate a planned window from an incident.", "Read core DB storage health: disk latency and IOPS via the storage API or vendor MIB, plus capacity used.", "Run the debit-visible assertion: the synthetic payment debit must appear in the journal within the agreed seconds."],
   questions: ["Is the slowdown uniform, or concentrated on one transaction type or GL path?", "Is a batch, index maintenance or archival job overlapping the online window?"] },
  "core.Pending-age p95": {
   checks: ["Read the maximum age of unposted or pending Pay Bill items (band <15 min intraday) - this is the metric that exposes a silently stuck core queue.", "Alert on a sustained rise across intervals, not on a single sample.", "Read pay.Technical decline and biller.Debits awaiting credit - items aging here become orphaned debits downstream.", "Read the batch window markers to confirm whether the queue is simply behind a planned window."],
   questions: ["What is the oldest pending item, and in what state is it stuck?", "Will these clear on their own inside the settlement window, or do they need manual posting?"] },
  "core.Batch overrun": {
   checks: ["Read the batch started and batch completed markers against the agreed window; alert on start-not-seen-by T+n as well as on completion overrun.", "Compare this run against the trailing 30-day median duration - >1.5x is the usual alert threshold.", "Read core.Pending-age p95 and gw.Route p95: an overrunning batch bleeds into the online path as latency.", "Read bbatch.Cut-off buffer - an overrun that eats the cut-off turns an infrastructure event into a settlement event."],
   questions: ["Which job in the chain is long, and what is its input volume versus a normal night?", "How much cut-off buffer is left before the biller advice file misses its deadline?"] },
  "bhub.Availability": {
   checks: ["Probe the hub echo or heartbeat endpoint with a 5 s timeout budget, and confirm it answers for more than one adapter.", "Read partner link state: IPsec tunnel status via SNMP (Cisco cipSecTunStatus 1.3.6.1.4.1.9.9.171.1.3.2.1.51; other vendor MIBs vary - confirm per device).", "Split by adapter - the hub is rarely down as a whole; usually one biller adapter is.", "Run the seeded test bill inquiry: it must return the known amount, which asserts the answer and not just the connection."],
   questions: ["Which adapters are affected, and do they share a route, credential or endpoint?", "What is the aggregator incident reference, severity and stated ETA?"] },
  "bhub.Inquiry p95": {
   checks: ["Read inquiry p95 per biller adapter, never blended - one slow biller disappears into the aggregate.", "Assert observed p95 sits inside the contracted timeout with headroom (an 8 s contract warrants an alert at p95 >5 s).", "Check the partner path: tunnel status, packet loss and interface error deltas on the egress link.", "Compare with pay.Orchestration p95 to see how much of the customer wait this hop owns."],
   questions: ["Which biller is slow, and is the partner reporting degradation on their side?", "Is our timeout budget still smaller than the orchestrator's, or are retries stacking?"] },
  "bhub.Adapter error": {
   checks: ["Split adapter errors by biller, error class and HTTP or SOAP fault code from the hub log.", "Run the contract check on the affected adapter - validate a live response against the pinned schema; silent field renames present as adapter errors.", "Confirm credentials and certificates on that adapter are current, and note the last rotation date.", "Check whether the errors begin at one of our deploy markers or at a partner release boundary."],
   questions: ["Did the biller change their API contract, endpoint or certificate without notice?", "Is the error mapped to a clean customer message, or does it surface as a technical decline?"] },
  "bhub.Biller timeout": {
   checks: ["Read the timeout rate per biller against that biller's contracted response time.", "Confirm the timeout hierarchy: each inner hop must be shorter than its caller's, or retries stack into a customer-visible failure.", "Run the idempotency replay assertion on the seeded biller - a timeout followed by a retry is the classic double-post risk.", "Read biller.Debits awaiting credit for money already moved against a timed-out leg."],
   questions: ["For the timed-out legs, did the biller actually receive and process the request?", "What is the partner's stated position on in-flight transactions during a brownout?"] },
  "biller.Credit-leg success (worst biller)": {
   checks: ["Read credit-leg success per biller, never blended - the worst biller sets the customer experience.", "Run the orphaned-debit sweep over the last 1-2 h: a failed credit leg with a posted debit is a business failure, not a technical one.", "Confirm the callback receiver is accepting confirmations - a healthy credit leg with a broken callback looks identical from our side.", "Run the seeded end-to-end payment against the test biller and assert post-conditions, not the HTTP response."],
   questions: ["Which biller, which product, and from what timestamp - and does their log agree with ours?", "How will the partner settle or reverse the affected legs, and on what timetable?"] },
  "biller.Availability": {
   checks: ["Probe the biller echo or heartbeat endpoint; where none exists, use a read-only balance enquiry on a seeded account as the stand-in.", "Read partner link state (IPsec tunnel via SNMP; vendor MIB varies) to separate the partner from the path to them.", "Check whether all billers or one are affected - one down is routing, all down is the hub or the egress path.", "Read bhub.Adapter error and bhub.Biller timeout for the same window."],
   questions: ["Is the partner in a planned maintenance window, and was notice actually given?", "What is the agreed fallback - queue and replay, or decline cleanly at inquiry?"] },
  "biller.Debits awaiting credit": {
   checks: ["Run the orphaned-debit sweep: read-only join of core debits to biller credits over a trailing 1-2 h window, plus the daily off-peak deep sweep.", "Capture amount, account, biller and age for each item - that list is the evidence bundle the ticket needs.", "Run the duplicate-posting detector alongside: same idempotency key, or same account, biller, amount and minute twice.", "Confirm whether the retry policy will still act on these items or whether they have exhausted retries."],
   questions: ["What is the total value at risk right now, and how old is the oldest item?", "Who confirms the credit landed - our callback, the partner file, or T+1 recon?"] },
  "biller.Top-up value delivery": {
   checks: ["Compare requested value against delivered value per top-up product - a short delivery is a business failure wearing a 200 OK.", "Read the partner delivery confirmations and reconcile them against our submitted amounts.", "Check whether shortfalls cluster on one denomination, product or carrier.", "Run the seeded top-up assertion and confirm the receipt amount matches the posted amount."],
   questions: ["Is the shortfall a promotion, rounding or tariff change on the partner side?", "How are affected customers identified and made whole, and by whom?"] },
  /* --- P-D after the payment (S13-S14) + batch --- */
  "bbatch.Advice-file age": {
   checks: ["List the advice-file directory read-only and assert the expected filename pattern exists, is non-zero, and is size-stable across two polls - arrived is not the same as finished writing.", "Check the .done or trailer marker where the partner provides one.", "Read the age of the newest accepted file against the agreed cycle, not against wall-clock alone.", "Read bbatch.Confirmation lag - a stale advice file and a lagging confirmation are usually the same event seen twice."],
   questions: ["Did the partner generate the file and fail to transfer it, or not generate it at all?", "What is their restated delivery time, and does it still fit inside our cut-off?"] },
  "bbatch.Cut-off buffer": {
   checks: ["Compute the minutes remaining to the settlement cut-off using the batch marker feed for the current run's progress.", "Read core.Batch overrun - an overrunning core batch is the usual reason the buffer shrinks.", "Confirm the clocks used for the cut-off decision agree (NTP offset <100 ms); skew silently moves the deadline.", "Read bbatch.Retry queue - anything still queued at cut-off rolls into the next cycle."],
   questions: ["What is the hard consequence of missing this cut-off - next-cycle rollover, penalty, or customer-visible delay?", "Can the partner accept a late file today, and who authorises that on both sides?"] },
  "bbatch.Retry queue": {
   checks: ["Read queue depth and, more importantly, the age of the oldest queued item - age is the customer's wait, depth is a volume artefact.", "Split by failure reason: a single repeating reason means retries will never clear it.", "Confirm the retry path is idempotent for these items - replaying without an idempotency key is how double-posts happen.", "Read bhub.Adapter error and biller.Availability for the upstream cause."],
   questions: ["Which items have exhausted their retries, and what is the manual path for them?", "Is the queue draining, flat or growing across the last three intervals?"] },
  "bbatch.Confirmation lag": {
   checks: ["Measure advice-file submission to partner confirmation against the agreed cycle.", "Confirm our own confirmation ingest is healthy - a missing confirmation may be an ingest failure on our side.", "Read recon.Match rate and recon.Exceptions open: unconfirmed advices become recon exceptions tomorrow morning.", "Read biller.Debits awaiting credit for the money exposure sitting behind the lag."],
   questions: ["Has the partner sent the confirmation, and to which endpoint or SFTP path?", "What is the agreed confirmation SLA, and when was it last met?"] },
  "mq.Availability": {
   checks: ["TCP-connect to the broker port and read the management API status; for Kafka, issue a metadata request against the bootstrap servers.", "Read cluster health: controller present, under-replicated partitions at zero, ISR complete.", "Read sysUpTime on the broker hosts for an unplanned restart between polls.", "Confirm producers are still accepting - a broker that reads healthy while producers fail is a partition, quota or ACL problem."],
   questions: ["Is this one broker or the cluster, and is the controller stable?", "Did a topic, partition or ACL change land in this window?"] },
  "mq.DLQ depth": {
   checks: ["Read DLQ depth per topic and, more usefully, the reason codes on the newest dead-lettered messages.", "Check whether the poison messages share a schema version, a producer or one transaction pattern.", "Read consumer lag alongside: kafka-consumer-groups.sh --describe --group <group>, where LAG = LOG-END-OFFSET minus CURRENT-OFFSET.", "Trace one dead-lettered payment end to end - if the money moved and only history failed, the priority changes."],
   questions: ["What is the common failure reason, and is the producer or the consumer at fault?", "Which of these messages represent completed payments whose history is now missing?"] },
  "mq.Oldest message age": {
   checks: ["Read oldest-message age per topic - age alarms better than depth (band <60 s for interactive payment queues).", "Read consumer-group lag with kafka-consumer-groups.sh --describe and identify which partitions are behind.", "Decide whether consumers are alive but slow (rebalancing, GC, downstream write latency) or stopped entirely.", "Run the history-visible assertion: the synthetic payment must appear in the statement API within 15 minutes."],
   questions: ["Are all partitions behind, or is one partition hot or unassigned?", "What downstream write is the consumer blocked on?"] },
  "mq.Notif delivery": {
   checks: ["Read delivery rate and p90 delay from provider receipts and queue metrics.", "Probe the push provider API status and confirm the SMS fallback route is actually being taken when push fails.", "Split by channel and platform (push iOS, push Android, SMS) - a token or certificate problem hits one platform only.", "Run the receipt-content assertion on the synthetic run: the confirmation amount must match the posted amount."],
   questions: ["Did the payment succeed and only the receipt fail? That is a comms incident, not a payments one.", "Are push credentials or provider certificates near expiry or recently rotated?"] },
  "recon.Availability": {
   checks: ["Confirm the recon run started on schedule and that settlement files arrived by deadline, size-stable across two polls.", "Confirm the SFTP or file server is reachable and the ingest job can write the archive path - read the job log, not the mount.", "Read sysUpTime on the recon host and the scheduler's last successful run.", "Confirm the exception queue is being written at all - a silent recon is worse than a failing one."],
   questions: ["Did the run start, and if it started, where exactly did it stop?", "Which upstream file is missing, and who owns its delivery?"] },
  "recon.Match rate": {
   checks: ["Read match rate against the three-way rule set (once, amount, order, window) and split misses by leg: gateway, core, biller.", "Separate timing misses (will match next cycle) from true breaks - they have different owners.", "Confirm contributing-system clocks agree; skew produces phantom out-of-window items and invalidates the whole timeline.", "Run the closure assertion: every synthetic payment from S04 must appear matched the next morning."],
   questions: ["Which leg is missing most often, and does that map onto a known incident window?", "Are the unmatched items customer-visible yet, or still inside the settlement window?"] },
  "recon.Exceptions open": {
   checks: ["Read open exception count together with the exception age trend - age matters more than count.", "Group exceptions by cause and by counterparty to find the single upstream event behind them.", "Read recon.Unmatched value for the money at risk sitting behind the count.", "Confirm the previous cycle's exceptions actually closed rather than being silently carried forward."],
   questions: ["Which incident window do the oldest exceptions trace back to?", "Who is working the queue, and what is the daily clear rate versus arrival rate?"] },
  "recon.Unmatched value": {
   checks: ["Sum unmatched debits over the trailing window - this is the value-at-risk figure for the ticket and the CTO tile (label it ILLUSTRATIVE where seeded).", "Split by counterparty and by age band; value concentrated in one biller names the owner immediately.", "Cross-check biller.Debits awaiting credit and the orphaned-debit sweep - the same money should appear in both views.", "Confirm nothing is double-counted across cycles before the figure leaves the room."],
   questions: ["What is the customer-facing exposure - debited and not delivered - as distinct from timing differences?", "What is the agreed remediation path and timetable with the counterparty?"] }
 }
};
